package com.muxigame.city;
import java.util.*;
import net.minecraft.commands.Commands;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
/** Admin entry points; test fixture is explicit and refuses occupied terrain. */
public final class RuralCommands {
 static void register(RegisterCommandsEvent event){event.getDispatcher().register(Commands.literal("rural").requires(s->s.hasPermission(2)).then(Commands.literal("give").executes(ctx->{var p=ctx.getSource().getPlayerOrException();for(var item:RuralBlocks.ITEMS)p.getInventory().placeItemBackInInventory(new ItemStack(item.get()));p.getInventory().placeItemBackInInventory(new ItemStack(RuralBlocks.STORAGE_WAND.get()));p.getInventory().placeItemBackInInventory(new ItemStack(RuralBlocks.MARRIAGE_WAND.get()));return 1;})).then(Commands.literal("help").executes(ctx->{ctx.getSource().sendSuccess(()->Component.literal("农村：先划定村落并登记NPC与麦田落成。/rural give 领取三个工作点、专用储藏箱及两根魔杖。储存魔杖：NPC→工作点→专用箱；婚姻魔杖：依次两人→关系按钮。空手点工作点打开家庭页并启用。右键专用储藏箱打开27格界面，统计粮食总量最多10份。普通箱不参与家庭绑定。"),false);return 1;})).then(Commands.literal("report").executes(ctx->{var p=ctx.getSource().getPlayerOrException();var c=RuralTools.city(p.serverLevel(),p.blockPosition());CityEconomy.require(c!=null,"请站在村落内");ctx.getSource().sendSuccess(()->Component.literal(RuralSettlement.get(p.server).report(p.server,c)),false);return 1;})).then(Commands.literal("audit").executes(ctx->{var p=ctx.getSource().getPlayerOrException();var c=RuralTools.city(p.serverLevel(),p.blockPosition());CityEconomy.require(c!=null&&(c.name.equals("农村主粮验证")||c.name.equals("猎户农村夜间观察")),"仅限专用验证场");var d=RuralSettlement.get(p.server);for(int i=1;i<=120;i++){for(var person:d.state.people.values()){var family=d.state.families.get(person.family);if(family!=null&&c.id.equals(family.city))person.workingTicks=(i-1)%20<10?1200:0;}d.cycle(p.server,c,i%30==0,i%60==0);}d.setDirty();ctx.getSource().sendSuccess(()->Component.literal("验证场合成2小时（含1小时工作，并非实际运行时长）："+d.report(p.server,c)),false);return 1;})).then(Commands.literal("monitor").executes(ctx->{var p=ctx.getSource().getPlayerOrException();var c=RuralTools.city(p.serverLevel(),p.blockPosition());CityEconomy.require(c!=null,"请站在测试村内");RuralMonitor.start(p.server,c.id);ctx.getSource().sendSuccess(()->Component.literal("已启用12运行小时监控，每5分钟写入world/city_settlements/rural-monitor，无AI轮询"),false);return 1;}).then(Commands.literal("stop").executes(ctx->{var d=RuralSettlement.get(ctx.getSource().getServer());d.state.monitored.clear();d.setDirty();return 1;}))).then(Commands.literal("hunterreset").executes(ctx->{try{HunterVillage.resetPreflight(ctx.getSource().getPlayerOrException());return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})).then(Commands.literal("hunterdemo").executes(ctx->{var p=ctx.getSource().getPlayerOrException();try{HunterVillage.create(p);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})).then(Commands.literal("demo").executes(ctx->{var p=ctx.getSource().getPlayerOrException();try{demo(p);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));}
 static void demo(net.minecraft.server.level.ServerPlayer p){var level=p.serverLevel();BlockPos origin=p.blockPosition().offset(3,0,3);var bounds=CityBounds.between(origin,origin.offset(15,4,8));CityEconomy.require(level.hasChunkAt(bounds.min())&&level.hasChunkAt(bounds.max()),"请先靠近加载示范区域");for(int i=0;i<bounds.volume();i++)CityEconomy.require(level.getBlockState(bounds.at(i)).isAir(),"示范区域必须全部为空，不覆盖已有建筑");var cities=CityData.get(p.server);cities.checkBounds(null,level.dimension().location().toString(),bounds);var type=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.get(net.minecraft.resources.ResourceLocation.parse("customnpcs:customnpc"));CityEconomy.require(type!=null,"需要CustomNPCs");var c=cities.create(p.getUUID(),"农村主粮验证",level.dimension().location().toString(),bounds);var rural=RuralSettlement.get(p.server);var ids=new ArrayList<UUID>();for(int i=0;i<3;i++){var e=type.create(level);CityEconomy.require(e instanceof net.minecraft.world.entity.LivingEntity,"NPC创建失败");e.setPos(origin.getX()+2+i*5,origin.getY()+1,origin.getZ()+2);e.setCustomName(Component.literal(new String[]{"试验农夫","试验农妇","试验头人"}[i]));if(e instanceof net.minecraft.world.entity.Mob mob)mob.setNoAi(true);level.addFreshEntity(e);c.residents.add(e.getUUID());rural.enroll(p.server,c,e.getUUID(),e.getName().getString());ids.add(e.getUUID());}
  var a=rural.state.people.get(ids.get(0));var b=rural.state.people.get(ids.get(1));var fa=rural.state.families.get(a.family);var old=b.family;RuralRules.admit(fa,b,rural.state.people);rural.state.families.remove(old);a.spouse=b.id;b.spouse=a.id;a.marriage=b.marriage=RuralRules.Marriage.FACTUAL;
  for(int x=0;x<16;x++)for(int z=0;z<9;z++)level.setBlock(origin.offset(x,0,z),Blocks.STONE_BRICKS.defaultBlockState(),3);
  var plan=CityMaintenance.get(p.server).state.cities.computeIfAbsent(c.id,k->new CityMaintenance.Plan());for(int x=0;x<5;x++)for(int z=4;z<8;z++){var pos=origin.offset(x,1,z);level.setBlock(pos,Blocks.FARMLAND.defaultBlockState(),3);level.setBlock(pos.above(),Blocks.WHEAT.defaultBlockState(),3);plan.baseline.put(pos.above().asLong(),CityMaintenance.encode(Blocks.WHEAT.defaultBlockState()));}plan.healthyPlots=20;
  var blocks=List.of(RuralBlocks.SIFTER.get(),RuralBlocks.STOVE.get(),RuralBlocks.DESK.get());for(int i=0;i<3;i++){var pos=origin.offset(2+i*5,1,1);level.setBlock(pos,blocks.get(i).defaultBlockState(),3);RuralTools.register(level,pos,(RuralBlocks.Link)level.getBlockEntity(pos));var person=rural.state.people.get(ids.get(i));var site=rural.state.sites.get(RuralSettlement.key(c.id,pos.asLong()));site.worker=person.id;person.role=RuralRules.Role.values()[i+1];person.trainedHours=10;for(int n=0;n<3;n++){var boxPos=origin.offset(1+i*5+n,1,3);level.setBlock(boxPos,RuralBlocks.CHEST.get().defaultBlockState(),3);var link=(RuralBlocks.Link)level.getBlockEntity(boxPos);link.offset=pos.subtract(boxPos);link.setChanged();RuralTools.register(level,boxPos,link);}}
  // Explicit test seed only, never a recurring refill.
  for(var box:rural.state.boxes.values())if(box.city.equals(c.id)){box.stock.wheat=6;box.stock.bread=4;}rural.log("管理员创建验证场：每箱6小麦4面包，一次性测试种子库存");rural.enable(p.server,c);CityMaintenance.get(p.server).setDirty();cities.setDirty();RuralTools.selected.put(p.getUUID(),a.id);RuralTools.snapshot(p,a.id,"测试场已创建：20麦田、三职业、一次性种子库存；不会自动补钱补粮。");
 }
}



